from itertools import combinations_with_replacement
def polyfit(deg, cols):
    feats=[np.ones_like(x)]
    for d in range(1,deg+1):
        for comb in combinations_with_replacement(range(len(cols)),d):
            f=np.ones_like(x)
            for i in comb: f=f*cols[i]
            feats.append(f)
    A=np.column_stack(feats)
    c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
    return np.mean((A@c-dv_dt)**2)/np.var(dv_dt)
